import os

def create(path, content, label):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    print(f"[OK] {label}")

# ============================================================================
# CallManager.kt aur CallScreen.kt dono ko poora replace kar rahe hain
# (in dono files mein changes bahut jagah bikhre hain, isliye str_replace ke
# bajaye poora file overwrite karna safe hai). Yeh files sirf calling
# feature ke liye hain, koi aur screen isse touch nahi karti.
#
# CallManager.kt fix: ICE candidates ab buffer hote hain jab tak remote SDP
# set nahi hota (ringing ke dauraan) -- pehle yeh silently drop ho jaate the
# jisse call connect hone mein dikkat aati thi.
#
# CallScreen.kt fix: avatar ab cache + live API dono se fetch hota hai (pehle
# sirf cache padhta tha, isliye pehli baar kisi ko call karne pe photo kabhi
# load hi nahi hoti thi), aur load hone tak chhota spinner dikhta hai.
# ============================================================================

create(
    "app/src/main/java/com/muwan/muwanchat/calling/CallManager.kt",
'package com.muwan.muwanchat.calling\n\nimport android.content.Context\nimport android.media.AudioManager\nimport org.webrtc.AudioSource\nimport org.webrtc.AudioTrack\nimport org.webrtc.DefaultVideoDecoderFactory\nimport org.webrtc.DefaultVideoEncoderFactory\nimport org.webrtc.EglBase\nimport org.webrtc.IceCandidate\nimport org.webrtc.MediaConstraints\nimport org.webrtc.PeerConnection\nimport org.webrtc.PeerConnectionFactory\nimport org.webrtc.SdpObserver\nimport org.webrtc.SessionDescription\nimport org.webrtc.audio.JavaAudioDeviceModule\n\n/**\n * WebRTC ka poora kaam yahan hota hai -- PeerConnectionFactory init, local\n * audio track banana, offer/answer create karna, ICE candidates handle\n * karna. CallScreen.kt sirf iske callbacks use karta hai, WebRTC ke internal\n * types se seedha waasta nahi rakhta -- taaki UI clean rahe aur video call\n * (Phase 2) add karte waqt yeh class hi extend ho, UI dobara na likhni pade.\n *\n * NOTE (TURN): Abhi sirf free public STUN hai. Cross-network (jaise ek WiFi\n * ek mobile-data) call test karne se pehle Metered.ca ka free Open Relay\n * TURN account bana ke neeche TURN_USERNAME/TURN_CREDENTIAL fill karo --\n * warna restrictive networks pe call connect nahi hogi.\n */\nclass CallManager(\n    private val context: Context,\n    private val onLocalIceCandidate: (IceCandidate) -> Unit,\n    private val onRemoteAudioTrackAdded: () -> Unit,\n    private val onConnectionFailed: () -> Unit\n) {\n    private var peerConnectionFactory: PeerConnectionFactory? = null\n    private var peerConnection: PeerConnection? = null\n    private var localAudioTrack: AudioTrack? = null\n    private var audioSource: AudioSource? = null\n    private val eglBase: EglBase by lazy { EglBase.create() }\n\n    private val audioManager by lazy {\n        context.getSystemService(Context.AUDIO_SERVICE) as AudioManager\n    }\n\n    // TODO: Metered.ca "Open Relay Project" se free account banao aur yeh\n    // 2 values fill karo (20GB/month free, no credit card required).\n    private val TURN_USERNAME = "REPLACE_WITH_METERED_USERNAME"\n    private val TURN_CREDENTIAL = "REPLACE_WITH_METERED_CREDENTIAL"\n\n    private val iceServers: List<PeerConnection.IceServer>\n        get() = listOf(\n            PeerConnection.IceServer.builder("stun:stun.relay.metered.ca:80").createIceServer(),\n            PeerConnection.IceServer.builder("stun:stun.l.google.com:19302").createIceServer(),\n            PeerConnection.IceServer.builder("turn:global.relay.metered.ca:80")\n                .setUsername(TURN_USERNAME)\n                .setPassword(TURN_CREDENTIAL)\n                .createIceServer()\n        )\n\n    fun init() {\n        val options = PeerConnectionFactory.InitializationOptions.builder(context)\n            .setEnableInternalTracer(false)\n            .createInitializationOptions()\n        PeerConnectionFactory.initialize(options)\n\n        val adm = JavaAudioDeviceModule.builder(context)\n            .setUseHardwareAcousticEchoCanceler(true)\n            .setUseHardwareNoiseSuppressor(true)\n            .createAudioDeviceModule()\n\n        peerConnectionFactory = PeerConnectionFactory.builder()\n            .setAudioDeviceModule(adm)\n            .setVideoEncoderFactory(DefaultVideoEncoderFactory(eglBase.eglBaseContext, true, true))\n            .setVideoDecoderFactory(DefaultVideoDecoderFactory(eglBase.eglBaseContext))\n            .createPeerConnectionFactory()\n\n        adm.release()\n    }\n\n    /** Naya PeerConnection banata hai (caller aur callee dono ke liye same) */\n    private fun createPeerConnection() {\n        val rtcConfig = PeerConnection.RTCConfiguration(iceServers).apply {\n            sdpSemantics = PeerConnection.SdpSemantics.UNIFIED_PLAN\n        }\n        peerConnection = peerConnectionFactory?.createPeerConnection(\n            rtcConfig,\n            object : PeerConnection.Observer {\n                override fun onIceCandidate(candidate: IceCandidate) {\n                    onLocalIceCandidate(candidate)\n                }\n                override fun onAddTrack(\n                    receiver: org.webrtc.RtpReceiver,\n                    streams: Array<out org.webrtc.MediaStream>\n                ) {\n                    if (receiver.track()?.kind() == "audio") onRemoteAudioTrackAdded()\n                }\n                override fun onConnectionChange(newState: PeerConnection.PeerConnectionState) {\n                    if (newState == PeerConnection.PeerConnectionState.FAILED ||\n                        newState == PeerConnection.PeerConnectionState.DISCONNECTED\n                    ) {\n                        onConnectionFailed()\n                    }\n                }\n                override fun onSignalingChange(p0: PeerConnection.SignalingState?) {}\n                override fun onIceConnectionChange(p0: PeerConnection.IceConnectionState?) {}\n                override fun onIceConnectionReceivingChange(p0: Boolean) {}\n                override fun onIceGatheringChange(p0: PeerConnection.IceGatheringState?) {}\n                override fun onIceCandidatesRemoved(p0: Array<out IceCandidate>?) {}\n                override fun onAddStream(p0: org.webrtc.MediaStream?) {}\n                override fun onRemoveStream(p0: org.webrtc.MediaStream?) {}\n                override fun onDataChannel(p0: org.webrtc.DataChannel?) {}\n                override fun onRenegotiationNeeded() {}\n            }\n        )\n        addLocalAudioTrack()\n    }\n\n    private fun addLocalAudioTrack() {\n        val factory = peerConnectionFactory ?: return\n        audioSource = factory.createAudioSource(MediaConstraints())\n        localAudioTrack = factory.createAudioTrack("audio_track", audioSource)\n        peerConnection?.addTrack(localAudioTrack, listOf("audio_stream"))\n    }\n\n    /** Caller side: naya call shuru karte waqt offer banao */\n    fun createOffer(onSdpReady: (String) -> Unit) {\n        createPeerConnection()\n        val constraints = MediaConstraints()\n        peerConnection?.createOffer(object : SdpObserver {\n            override fun onCreateSuccess(desc: SessionDescription) {\n                peerConnection?.setLocalDescription(SimpleSdpObserver(), desc)\n                onSdpReady(desc.description)\n            }\n            override fun onCreateFailure(error: String?) {}\n            override fun onSetSuccess() {}\n            override fun onSetFailure(error: String?) {}\n        }, constraints)\n    }\n\n    /** Callee side: aaya hua offer set karke answer banao */\n    fun createAnswer(remoteSdp: String, onSdpReady: (String) -> Unit) {\n        createPeerConnection()\n        peerConnection?.setRemoteDescription(\n            object : SimpleSdpObserver() {\n                override fun onSetSuccess() {\n                    // Ab remote description set ho chuka hai, jo bhi ICE\n                    // candidates ringing ke dauraan queue hue the woh ab\n                    // safely apply ho sakte hain.\n                    flushPendingCandidates()\n                }\n            },\n            SessionDescription(SessionDescription.Type.OFFER, remoteSdp)\n        )\n        val constraints = MediaConstraints()\n        peerConnection?.createAnswer(object : SdpObserver {\n            override fun onCreateSuccess(desc: SessionDescription) {\n                peerConnection?.setLocalDescription(SimpleSdpObserver(), desc)\n                onSdpReady(desc.description)\n            }\n            override fun onCreateFailure(error: String?) {}\n            override fun onSetSuccess() {}\n            override fun onSetFailure(error: String?) {}\n        }, constraints)\n    }\n\n    /** Caller side: callee ka answer aaya, use apply karo */\n    fun setRemoteAnswer(remoteSdp: String) {\n        peerConnection?.setRemoteDescription(\n            object : SimpleSdpObserver() {\n                override fun onSetSuccess() {\n                    flushPendingCandidates()\n                }\n            },\n            SessionDescription(SessionDescription.Type.ANSWER, remoteSdp)\n        )\n    }\n\n    // Jab tak remote description set nahi hua (caller ke liye: jab tak answer\n    // nahi aaya; callee ke liye: jab tak offer set nahi hua), aane waale ICE\n    // candidates yahan queue ho jaate hain -- warna woh silently drop ho jaate\n    // the aur call connect hone mein dikkat aati thi.\n    private val pendingRemoteCandidates = mutableListOf<IceCandidate>()\n    private var remoteDescriptionSet = false\n\n    private fun flushPendingCandidates() {\n        remoteDescriptionSet = true\n        pendingRemoteCandidates.forEach { peerConnection?.addIceCandidate(it) }\n        pendingRemoteCandidates.clear()\n    }\n\n    fun addRemoteIceCandidate(sdpMid: String?, sdpMLineIndex: Int, candidate: String) {\n        val ice = IceCandidate(sdpMid, sdpMLineIndex, candidate)\n        if (!remoteDescriptionSet) {\n            pendingRemoteCandidates.add(ice)\n        } else {\n            peerConnection?.addIceCandidate(ice)\n        }\n    }\n\n    fun setMuted(muted: Boolean) {\n        localAudioTrack?.setEnabled(!muted)\n    }\n\n    fun setSpeakerOn(on: Boolean) {\n        audioManager.isSpeakerphoneOn = on\n        audioManager.mode = if (on) AudioManager.MODE_IN_COMMUNICATION else AudioManager.MODE_IN_COMMUNICATION\n    }\n\n    fun endCall() {\n        localAudioTrack?.dispose()\n        audioSource?.dispose()\n        peerConnection?.close()\n        peerConnection?.dispose()\n        peerConnection = null\n        localAudioTrack = null\n        audioSource = null\n        remoteDescriptionSet = false\n        pendingRemoteCandidates.clear()\n    }\n\n    fun release() {\n        endCall()\n        peerConnectionFactory?.dispose()\n        peerConnectionFactory = null\n    }\n}\n\n/** SdpObserver ke saare methods override karne se bachne ke liye chhota helper */\nprivate open class SimpleSdpObserver : SdpObserver {\n    override fun onCreateSuccess(p0: SessionDescription?) {}\n    override fun onSetSuccess() {}\n    override fun onCreateFailure(p0: String?) {}\n    override fun onSetFailure(p0: String?) {}\n}\n',
    "CallManager.kt: ICE candidate buffering fix"
)

create(
    "app/src/main/java/com/muwan/muwanchat/screens/CallScreen.kt",
'package com.muwan.muwanchat.screens\n\nimport android.Manifest\nimport android.content.pm.PackageManager\nimport android.widget.Toast\nimport androidx.activity.compose.rememberLauncherForActivityResult\nimport androidx.activity.result.contract.ActivityResultContracts\nimport androidx.compose.foundation.background\nimport androidx.compose.foundation.clickable\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.shape.CircleShape\nimport androidx.compose.material.icons.Icons\nimport androidx.compose.material.icons.filled.ArrowBack\nimport androidx.compose.material.icons.filled.Call\nimport androidx.compose.material.icons.filled.CallEnd\nimport androidx.compose.material.icons.filled.Mic\nimport androidx.compose.material.icons.filled.MicOff\nimport androidx.compose.material.icons.filled.VolumeOff\nimport androidx.compose.material.icons.filled.VolumeUp\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Alignment\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.graphics.Color\nimport androidx.compose.ui.graphics.vector.ImageVector\nimport androidx.compose.ui.platform.LocalContext\nimport androidx.compose.ui.text.font.FontWeight\nimport androidx.compose.ui.unit.Dp\nimport androidx.compose.ui.unit.dp\nimport androidx.compose.ui.unit.sp\nimport androidx.core.content.ContextCompat\nimport androidx.navigation.NavController\nimport com.muwan.muwanchat.calling.CallManager\nimport com.muwan.muwanchat.calling.PendingIncomingCall\nimport com.muwan.muwanchat.data.AuthDataStore\nimport com.muwan.muwanchat.data.MuwanChatDb\nimport com.muwan.muwanchat.data.AppSocketManager\nimport com.muwan.muwanchat.data.SocketEvent\nimport com.muwan.muwanchat.network.RetrofitClient\nimport kotlinx.coroutines.delay\nimport kotlinx.coroutines.flow.first\nimport kotlinx.coroutines.launch\nimport java.util.UUID\n\nprivate enum class CallState { RINGING_OUTGOING, RINGING_INCOMING, CONNECTING, ONGOING, ENDED }\n\n// Voice call screen -- WebRTC signaling (CallManager) + backend socket\n// events (AppSocketManager) dono se real-wired. isIncoming=true tab CallId\n// aur SDP PendingIncomingCall se aate hain (NavGraph ke global listener ne\n// wahan rakhe the), Accept/Decline UI dikhta hai. isIncoming=false tab yeh\n// screen khud offer banake bhejti hai aur "Ringing..." dikhata hai.\n@Composable\nfun CallScreen(\n    navController: NavController,\n    otherUid: String,\n    otherUsername: String,\n    callType: String,\n    isIncoming: Boolean\n) {\n    val context = LocalContext.current\n    val scope = rememberCoroutineScope()\n    val db = remember { MuwanChatDb.get(context, AuthDataStore.getUidBlocking(context)) }\n\n    val incomingData = remember { if (isIncoming) PendingIncomingCall.data else null }\n    LaunchedEffect(Unit) { PendingIncomingCall.data = null } // consume kar liya, dobara use na ho\n\n    val callId = remember { incomingData?.callId ?: UUID.randomUUID().toString() }\n\n    var avatarBase64 by remember { mutableStateOf<String?>(null) }\n    var isAvatarLoading by remember { mutableStateOf(true) }\n    var isMuted by remember { mutableStateOf(false) }\n    var isSpeakerOn by remember { mutableStateOf(false) }\n    var callState by remember {\n        mutableStateOf(if (isIncoming) CallState.RINGING_INCOMING else CallState.RINGING_OUTGOING)\n    }\n    var durationSeconds by remember { mutableStateOf(0) }\n    var hasMicPermission by remember {\n        mutableStateOf(\n            ContextCompat.checkSelfPermission(context, Manifest.permission.RECORD_AUDIO) == PackageManager.PERMISSION_GRANTED\n        )\n    }\n\n    val micPermissionLauncher = rememberLauncherForActivityResult(\n        ActivityResultContracts.RequestPermission()\n    ) { granted ->\n        hasMicPermission = granted\n        if (!granted) {\n            Toast.makeText(context, "Microphone permission is needed to make calls", Toast.LENGTH_SHORT).show()\n            navController.popBackStack()\n        }\n    }\n\n    LaunchedEffect(Unit) {\n        if (!hasMicPermission) micPermissionLauncher.launch(Manifest.permission.RECORD_AUDIO)\n    }\n\n    // CallManager ek hi baar banta hai, screen ke poore lifecycle mein reuse hota hai\n    val callManager = remember {\n        CallManager(\n            context = context,\n            onLocalIceCandidate = { candidate ->\n                AppSocketManager.sendIceCandidate(callId, candidate.sdpMid, candidate.sdpMLineIndex, candidate.sdp)\n            },\n            onRemoteAudioTrackAdded = { /* audio apne aap play hota hai WebRTC se, UI change ki zaroorat nahi */ },\n            onConnectionFailed = {\n                if (callState != CallState.ENDED) {\n                    callState = CallState.ENDED\n                    navController.popBackStack()\n                }\n            }\n        )\n    }\n    val ringtoneManager = remember { com.muwan.muwanchat.calling.CallRingtoneManager(context) }\n\n    // Incoming call pe ringtone+vibration, outgoing pe ringback tone -- jaise\n    // hi state ringing se aage badhe (connecting/ongoing/ended), band ho jaata hai\n    LaunchedEffect(callState) {\n        when (callState) {\n            CallState.RINGING_INCOMING -> ringtoneManager.startIncomingRing()\n            CallState.RINGING_OUTGOING -> ringtoneManager.startOutgoingRingback()\n            else -> ringtoneManager.stop()\n        }\n    }\n\n    // Outgoing call: offer khud banao aur bhejo\n    LaunchedEffect(hasMicPermission) {\n        if (hasMicPermission && !isIncoming && callState == CallState.RINGING_OUTGOING) {\n            callManager.init()\n            callManager.createOffer { sdp ->\n                AppSocketManager.sendCallOffer(callId, otherUid, callType, sdp) { success, error ->\n                    if (!success) {\n                        Toast.makeText(\n                            context,\n                            if (error == "busy") "User is on another call" else "Could not start call",\n                            Toast.LENGTH_SHORT\n                        ).show()\n                        navController.popBackStack()\n                    }\n                }\n            }\n        } else if (hasMicPermission && isIncoming) {\n            callManager.init()\n        }\n    }\n\n    // Backend se aane wale call events suno\n    LaunchedEffect(Unit) {\n        AppSocketManager.events.collect { event ->\n            when (event) {\n                is SocketEvent.CallAnswerReceived -> {\n                    if (event.callId == callId && !isIncoming) {\n                        callManager.setRemoteAnswer(event.sdp)\n                        callState = CallState.ONGOING\n                    }\n                }\n                is SocketEvent.IceCandidateReceived -> {\n                    if (event.callId == callId) {\n                        callManager.addRemoteIceCandidate(event.sdpMid, event.sdpMLineIndex, event.candidate)\n                    }\n                }\n                is SocketEvent.CallEndReceived -> {\n                    if (event.callId == callId) {\n                        callState = CallState.ENDED\n                        callManager.release()\n                        navController.popBackStack()\n                    }\n                }\n                is SocketEvent.CallBusyReceived -> {\n                    if (event.callId == callId) {\n                        Toast.makeText(context, "User is on another call", Toast.LENGTH_SHORT).show()\n                        callState = CallState.ENDED\n                        navController.popBackStack()\n                    }\n                }\n                else -> {}\n            }\n        }\n    }\n\n    // Ongoing call ka duration timer\n    LaunchedEffect(callState) {\n        if (callState == CallState.ONGOING) {\n            durationSeconds = 0\n            while (true) {\n                delay(1000)\n                durationSeconds++\n            }\n        }\n    }\n\n    // Screen band ho (back button, ya kisi aur wajah se) toh cleanup zaroor ho\n    DisposableEffect(Unit) {\n        onDispose {\n            if (callState != CallState.ENDED) {\n                AppSocketManager.sendCallEnd(callId)\n            }\n            callManager.release()\n            ringtoneManager.stop()\n        }\n    }\n\n    // Cache se turant dikhao (agar hai), phir background me API se fresh photo\n    // laao -- pehle sirf cache padhte the isliye pehli-baar-call-karne pe\n    // (jab profile pehle kabhi khola na ho) avatar kabhi load hi nahi hota tha.\n    LaunchedEffect(otherUid) {\n        val cached = db.cachedUserProfileDao().get(otherUid)\n        if (cached?.avatar != null) {\n            avatarBase64 = cached.avatar\n            isAvatarLoading = false\n        }\n        try {\n            val token = AuthDataStore.getToken(context).first() ?: return@LaunchedEffect\n            val res = RetrofitClient.usersApi.getUserByUid("Bearer $token", otherUid)\n            val fresh = res.body()?.user\n            if (fresh != null) {\n                avatarBase64 = fresh.avatar\n                db.cachedUserProfileDao().upsert(\n                    com.muwan.muwanchat.data.CachedUserProfileEntity(\n                        uid = fresh.uid,\n                        username = fresh.username,\n                        name = fresh.name,\n                        bio = fresh.bio,\n                        city = fresh.city,\n                        country = fresh.country,\n                        gender = fresh.gender,\n                        avatar = fresh.avatar,\n                        status = cached?.status ?: "none"\n                    )\n                )\n            }\n        } catch (_: Exception) {\n            // Network fail ho toh bhi loader hata do -- fallback letter-avatar dikh jaayega\n        } finally {\n            isAvatarLoading = false\n        }\n    }\n\n    fun endCall() {\n        AppSocketManager.sendCallEnd(callId)\n        callState = CallState.ENDED\n        callManager.release()\n        navController.popBackStack()\n    }\n\n    fun acceptCall() {\n        val data = incomingData ?: return\n        callState = CallState.CONNECTING\n        callManager.createAnswer(data.sdp) { answerSdp ->\n            AppSocketManager.sendCallAnswer(callId, answerSdp)\n            callState = CallState.ONGOING\n        }\n    }\n\n    fun declineCall() {\n        AppSocketManager.sendCallReject(callId)\n        callState = CallState.ENDED\n        callManager.release()\n        navController.popBackStack()\n    }\n\n    Box(modifier = Modifier.fillMaxSize()) {\n        // Background: chat/group ka default space wallpaper, consistency ke liye\n        WallpaperPreviewBackground(entity = null)\n        Box(modifier = Modifier.fillMaxSize().background(Color(0x99000000)))\n\n        IconButton(\n            onClick = { navController.popBackStack() },\n            modifier = Modifier\n                .align(Alignment.TopStart)\n                .statusBarsPadding()\n                .padding(8.dp)\n        ) {\n            Icon(Icons.Filled.ArrowBack, contentDescription = "Back", tint = Color.White)\n        }\n\n        Column(\n            modifier = Modifier.align(Alignment.Center),\n            horizontalAlignment = Alignment.CenterHorizontally\n        ) {\n            Box(contentAlignment = Alignment.Center) {\n                AvatarView(\n                    avatarBase64 = avatarBase64,\n                    fallbackText = otherUsername,\n                    size = 120.dp,\n                    fontSize = 42.sp\n                )\n                // Photo load hone tak fallback-letter ke upar chhota spinner --\n                // shared AvatarView component ko touch nahi kiya, sirf yahan\n                // ek transparent overlay lagaya hai.\n                if (isAvatarLoading && avatarBase64 == null) {\n                    CircularProgressIndicator(\n                        modifier = Modifier.size(36.dp),\n                        color = Color.White,\n                        strokeWidth = 3.dp\n                    )\n                }\n            }\n            Spacer(Modifier.height(20.dp))\n            Text(otherUsername, color = Color.White, fontSize = 22.sp, fontWeight = FontWeight.Bold)\n            Spacer(Modifier.height(6.dp))\n            Text(\n                text = when (callState) {\n                    CallState.RINGING_OUTGOING -> "Ringing..."\n                    CallState.RINGING_INCOMING -> "Incoming voice call"\n                    CallState.CONNECTING -> "Connecting..."\n                    CallState.ONGOING -> formatDuration(durationSeconds)\n                    CallState.ENDED -> "Call ended"\n                },\n                color = Color(0xFFAAAAAA),\n                fontSize = 15.sp\n            )\n        }\n\n        // Bottom controls -- incoming call ke liye Accept/Decline, baaki sab ke liye Mute/End/Speaker\n        if (callState == CallState.RINGING_INCOMING) {\n            Row(\n                modifier = Modifier\n                    .align(Alignment.BottomCenter)\n                    .navigationBarsPadding()\n                    .padding(bottom = 48.dp),\n                horizontalArrangement = Arrangement.spacedBy(56.dp),\n                verticalAlignment = Alignment.CenterVertically\n            ) {\n                CallControlButton(\n                    icon = Icons.Filled.CallEnd,\n                    background = Color(0xFFFF3B30),\n                    iconTint = Color.White,\n                    onClick = { declineCall() }\n                )\n                CallControlButton(\n                    icon = Icons.Filled.Call,\n                    background = Color(0xFF34C759),\n                    iconTint = Color.White,\n                    onClick = { acceptCall() }\n                )\n            }\n        } else {\n            Row(\n                modifier = Modifier\n                    .align(Alignment.BottomCenter)\n                    .navigationBarsPadding()\n                    .padding(bottom = 48.dp),\n                horizontalArrangement = Arrangement.spacedBy(36.dp),\n                verticalAlignment = Alignment.CenterVertically\n            ) {\n                CallControlButton(\n                    icon = if (isMuted) Icons.Filled.MicOff else Icons.Filled.Mic,\n                    background = Color(0xFF2A2A2A),\n                    iconTint = Color.White,\n                    onClick = {\n                        isMuted = !isMuted\n                        callManager.setMuted(isMuted)\n                    }\n                )\n                CallControlButton(\n                    icon = Icons.Filled.CallEnd,\n                    background = Color(0xFFFF3B30),\n                    iconTint = Color.White,\n                    size = 64.dp,\n                    iconSize = 30.dp,\n                    onClick = { endCall() }\n                )\n                CallControlButton(\n                    icon = if (isSpeakerOn) Icons.Filled.VolumeUp else Icons.Filled.VolumeOff,\n                    background = Color(0xFF2A2A2A),\n                    iconTint = Color.White,\n                    onClick = {\n                        isSpeakerOn = !isSpeakerOn\n                        callManager.setSpeakerOn(isSpeakerOn)\n                    }\n                )\n            }\n        }\n    }\n}\n\nprivate fun formatDuration(seconds: Int): String {\n    val m = seconds / 60\n    val s = seconds % 60\n    return "%d:%02d".format(m, s)\n}\n\n@Composable\nprivate fun CallControlButton(\n    icon: ImageVector,\n    background: Color,\n    iconTint: Color,\n    size: Dp = 56.dp,\n    iconSize: Dp = 24.dp,\n    onClick: () -> Unit\n) {\n    Box(\n        modifier = Modifier\n            .size(size)\n            .background(background, CircleShape)\n            .clickable { onClick() },\n        contentAlignment = Alignment.Center\n    ) {\n        Icon(icon, contentDescription = null, tint = iconTint, modifier = Modifier.size(iconSize))\n    }\n}\n',
    "CallScreen.kt: avatar loading fix"
)

